  {
   "group": "Score calibration and robust aggregation",
   "why": "The scoring rules are a small, self-contained part of inference that can be changed without retraining and measured with additional thresholded and calibration metrics on BMAD."
  },
  {
   "group": "Label-efficient adaptation",
   "why": "Replacing mask supervision of the segmentation branch is a single change to the training targets whose effect is directly measurable as a label-cost curve on the three masked datasets."
  },
  {
   "group": "Compact normality modelling",
   "why": "The memory bank can be replaced at inference time and its memory, latency and accuracy compared without retraining."
  }
 ]
